def find_longest_palindrome(s):
    n = len(s)
    max_length = 0
    best_palindrome = ""

    # Check all possible palindromic substrings
    for i in range(n):
        for j in range(i, n):
            substring = s[i:j+1]
            if substring == substring[::-1]:
                # Check if we can split this palindrome into a prefix and a suffix of s
                prefix_length = i
                suffix_length = n - (j + 1)
                if prefix_length <= j + 1 and suffix_length <= i:
                    if j + 1 > max_length:
                        max_length = j + 1
                        best_palindrome = substring

    return best_palindrome

