import sys

def is_palindrome(s):
    return s == s[::-1]

def longest_palindromic_prefix_suffix(s):
    n = len(s)
    max_length = 0
    result = ""

    for i in range(n):
        # Check for palindromes centered at i
        # Odd length palindromes
        l, r = i, i
        while l >= 0 and r < n and s[l] == s[r]:
            if l == 0 or r == n - 1:
                if r - l + 1 > max_length:
                    max_length = r - l + 1
                    result = s[l:r+1]
            l -= 1
            r += 1

        # Even length palindromes
        l, r = i, i + 1
        while l >= 0 and r < n and s[l] == s[r]:
            if l == 0 or r == n - 1:
                if r - l + 1 > max_length:
                    max_length = r - l + 1
                    result = s[l:r+1]
            l -= 1
            r += 1

    return result

